from pathlib import Path

pages={
'desktop-about.html':'about.html','desktop-conference.html':'conference.html','desktop-exhibition.html':'exhibition.html','desktop-exhibitor-profile.html':'exhibition.html#exhibitor-profile','desktop-space-rental.html':'exhibition.html#space-rental','desktop-experience.html':'experience.html','desktop-creators.html':'creators.html','desktop-rice-masterchef.html':'rice-masterchef.html','desktop-artists.html':'artists.html','desktop-partnership.html':'partnership.html','desktop-plan-visit.html':'plan-visit.html','desktop-contact.html':'contact.html','desktop-media-coverage.html':'media-coverage.html'}

CSS=r'''<style id="shared-desktop-system">
:root{--shared-shell:min(1680px,calc(100% - 64px));--shared-rail:240px;--shared-gap:88px;--nav:88px;--sh:var(--shared-shell);--shell:var(--shared-shell);--side:max(32px,calc((100vw - 1680px)/2))}
body{min-width:1100px}body>header.mast,body>header.masthead,body>header.top{display:none!important}
.shell{width:var(--shared-shell)!important;margin-inline:auto!important}.eyebrow,.eye{font-size:13.2px!important;line-height:1!important;letter-spacing:.16em!important}
.head{grid-template-columns:var(--shared-rail) minmax(0,1fr)!important;gap:var(--shared-gap)!important;text-align:left!important}.head>.eyebrow,.head>.eye{padding-top:12px!important}.heading,.stitle{font-size:clamp(44px,3.7vw,66px)!important;line-height:.98!important}.lede,.lead{max-width:62ch}
.shared-mast{position:fixed;z-index:1200;inset:2px 0 auto;height:88px;background:#0d0d0bf8;border-bottom:1px solid #35332e;color:#faf0e6}.shared-mast-inner{width:min(1760px,calc(100% - 48px));height:100%;margin:auto;display:grid;grid-template-columns:190px minmax(0,1fr) auto;gap:24px;align-items:center}.shared-brand img{width:170px;height:55px;object-fit:contain;object-position:left center}.shared-utils{justify-self:start;display:flex;border:1px solid #35332e;background:#191916}.shared-search,.shared-doc{height:44px;border:0;border-right:1px solid #35332e;background:transparent;color:#aba49c;display:flex;align-items:center;justify-content:center}.shared-search{width:46px}.shared-search svg,.shared-doc svg{width:16px;height:16px;fill:none;stroke:#ebb341;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.shared-doc{padding:0 14px;gap:9px;font:600 11px Poppins,sans-serif;letter-spacing:.1em;text-transform:uppercase;white-space:nowrap}.shared-doc:last-child{border-right:0}.shared-search:hover,.shared-doc:hover{background:#2b2b27;color:#faf0e6}.shared-tools{display:flex;align-items:center;gap:8px}.shared-count{height:46px;min-width:158px;padding:6px 14px;display:flex;flex-direction:column;justify-content:center;border:1px solid #c98e25;background:#191916}.shared-count small{color:#ebb341;font:600 8px Poppins;letter-spacing:.13em;text-transform:uppercase}.shared-count strong{margin-top:2px;font:600 12px Poppins;font-variant-numeric:tabular-nums}.shared-login,.shared-register,.shared-menu-btn{height:46px}.shared-login,.shared-register{padding:0 16px;display:grid;place-items:center;border:1px solid #35332e;font:600 11px Poppins;letter-spacing:.1em;text-transform:uppercase}.shared-register{background:#ebb341;border-color:#ebb341;color:#0d0d0b}.shared-menu-btn{width:46px;border:1px solid #35332e;background:#191916;display:grid;place-content:center;gap:6px;cursor:pointer}.shared-menu-btn i{display:block;width:18px;height:1px;background:#faf0e6}.shared-shade{position:fixed;z-index:1201;inset:0;background:#0d0d0bb3;opacity:0;pointer-events:none;transition:opacity .25s cubic-bezier(.16,1,.3,1)}.shared-shade.on{opacity:1;pointer-events:auto}.shared-drawer{position:fixed;z-index:1202;right:0;top:0;width:min(430px,38vw);height:100vh;padding:30px 36px;background:#191916;color:#faf0e6;border-left:1px solid #35332e;transform:translateX(102%);transition:transform .45s cubic-bezier(.16,1,.3,1);overflow:auto}.shared-drawer.open{transform:none}.shared-drawer-head{display:flex;justify-content:space-between;align-items:center;padding-bottom:24px;border-bottom:1px solid #35332e}.shared-drawer-head img{width:150px;height:48px;object-fit:contain}.shared-close{width:44px;height:44px;border:1px solid #35332e;background:none;color:#faf0e6;font-size:22px}.shared-nav{margin-top:18px}.shared-nav>a,.shared-group>span{min-height:48px;display:flex;align-items:center;border-bottom:1px solid #35332e;font:600 16px Poppins}.shared-sub{padding:4px 0 12px 18px;border-bottom:1px solid #35332e}.shared-sub a{padding:7px 0;display:flex;justify-content:space-between;color:#aba49c;font:500 12px Poppins}.shared-sub i{font-style:normal;color:#c98e25;font-size:10px}.shared-drawer-foot{margin-top:24px;padding-top:20px;border-top:1px solid #35332e;display:flex;gap:8px}.shared-drawer-foot a{flex:1;height:46px;display:grid;place-items:center;border:1px solid #35332e;font:600 10px Poppins;text-transform:uppercase}.shared-drawer-foot a:first-child{background:#ebb341;color:#0d0d0b;border-color:#ebb341}.shared-search-panel{position:fixed;z-index:1203;left:50%;top:50%;width:min(720px,calc(100% - 64px));padding:34px;background:#faf0e6;color:#0d0d0b;border:1px solid #d8cec3;transform:translate(-50%,-46%);opacity:0;visibility:hidden;transition:opacity .2s,transform .28s cubic-bezier(.16,1,.3,1)}.shared-search-panel.open{opacity:1;visibility:visible;transform:translate(-50%,-50%)}.shared-search-head{display:flex;justify-content:space-between;align-items:start}.shared-search-head h2{margin:8px 0 0;font:600 32px Poppins;letter-spacing:-.04em}.shared-search-head span{color:#c98e25;font:600 9px Poppins;letter-spacing:.16em;text-transform:uppercase}.shared-search-links{margin-top:26px;display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#d8cec3;border:1px solid #d8cec3}.shared-search-links a{min-height:54px;padding:14px;background:#faf0e6;font:600 12px Poppins}.shared-search-links a:hover{background:#f3e8db}.shared-lock{overflow:hidden}
@media(max-width:1450px){.shared-mast-inner{width:calc(100% - 32px);grid-template-columns:184px minmax(0,1fr) auto;gap:16px}.shared-doc{padding-inline:11px}.shared-count{min-width:144px}.shared-login{display:none}}
@media(max-width:1260px){.shared-doc{width:44px;padding:0}.shared-doc span{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.shared-count{min-width:136px}}
@media(max-width:1400px){:root{--shared-rail:190px;--shared-gap:56px}}
@media(max-width:1180px){:root{--shared-rail:160px;--shared-gap:40px}.head{grid-template-columns:var(--shared-rail) minmax(0,1fr)!important;gap:var(--shared-gap)!important}}
</style>'''

NAV='''<header class="shared-mast"><div class="shared-mast-inner"><a class="shared-brand" href="desktop.html"><img src="https://ik.imagekit.io/18ab23oqaj/BIRC%20Ivory%20logo%20dates.png" alt="BIRC"></a><div class="shared-utils"><button class="shared-search" type="button" aria-label="Search BIRC"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4 4"/></svg></button><a class="shared-doc" href="https://api.birc.in/uploads/birc-1781162197449-632024568.pdf" target="_blank" rel="noopener"><svg viewBox="0 0 24 24"><path d="M6 3h9l3 3v15H6zM15 3v4h4M9 11h6M9 15h6"/></svg><span>EY report</span></a><a class="shared-doc" href="https://api.birc.in/uploads/birc-1784615646887-946540455.pdf" target="_blank" rel="noopener"><svg viewBox="0 0 24 24"><path d="M4 7h16v12H4zM8 7V5h8v2M4 12h16"/></svg><span>Buyer facilitation</span></a><a class="shared-doc" href="https://api.birc.in/uploads/birc-agenda-2026.pdf" target="_blank" rel="noopener"><svg viewBox="0 0 24 24"><rect x="4" y="5" width="16" height="15"/><path d="M8 3v4M16 3v4M4 10h16"/></svg><span>2026 agenda</span></a></div><div class="shared-tools"><div class="shared-count"><small>Opens in</small><strong data-shared-clock>00d 00h 00m</strong></div><a class="shared-login" href="https://birc.in/login">Login</a><a class="shared-register" href="register.html?type=visitor">Register ↗</a><button class="shared-menu-btn" type="button" aria-label="Open site menu" aria-expanded="false"><i></i><i></i></button></div></div></header><div class="shared-shade"></div><aside class="shared-drawer" aria-label="Site menu"><div class="shared-drawer-head"><img src="https://ik.imagekit.io/18ab23oqaj/BIRC%20Ivory%20logo%20dates.png" alt="BIRC"><button class="shared-close" type="button" aria-label="Close site menu">×</button></div><nav class="shared-nav"><a href="desktop.html">Home</a><a href="desktop-about.html">About</a><a href="desktop-conference.html">Conference</a><div class="shared-group"><span>Exhibition</span><div class="shared-sub"><a href="desktop-exhibition.html">Why exhibit <i>01</i></a><a href="desktop-exhibitor-profile.html">Exhibitor profile <i>02</i></a><a href="desktop-space-rental.html">Space rental <i>03</i></a></div></div><a href="desktop-experience.html">Experience</a><div class="shared-group"><span>Influencers</span><div class="shared-sub"><a href="desktop-creators.html">Content Creators <i>01</i></a><a href="desktop-rice-masterchef.html">Rice Masterchef <i>02</i></a><a href="desktop-artists.html">Artists <i>03</i></a></div></div><a href="desktop-partnership.html">Partnership</a><a href="desktop-plan-visit.html">Plan Visit</a><a href="desktop-contact.html">Contact</a><a href="desktop-media-coverage.html">Media coverage</a></nav><div class="shared-drawer-foot"><a data-mobile-link href="#">Mobile view</a><a href="https://birc.in/login">Login</a></div></aside><section class="shared-search-panel" aria-label="Site search"><div class="shared-search-head"><div><span>BIRC 2026</span><h2>Find your way around.</h2></div><button class="shared-close shared-search-close" type="button" aria-label="Close search">×</button></div><div class="shared-search-links"><a href="desktop-conference.html">Speakers & programme</a><a href="desktop-exhibition.html">Exhibition</a><a href="desktop-plan-visit.html">Plan your visit</a><a href="desktop-partnership.html">Partnership</a><a href="desktop-media-coverage.html">Media coverage</a><a href="desktop-contact.html">Contact</a></div></section>'''

JS=r'''<script id="shared-desktop-system-script">(function(){var menu=document.querySelector('.shared-menu-btn'),drawer=document.querySelector('.shared-drawer'),shade=document.querySelector('.shared-shade'),close=document.querySelector('.shared-drawer .shared-close'),search=document.querySelector('.shared-search'),panel=document.querySelector('.shared-search-panel'),searchClose=document.querySelector('.shared-search-close');function setMenu(o){drawer.classList.toggle('open',o);shade.classList.toggle('on',o);menu.setAttribute('aria-expanded',String(o));document.body.classList.toggle('shared-lock',o)}function setSearch(o){panel.classList.toggle('open',o);shade.classList.toggle('on',o);document.body.classList.toggle('shared-lock',o)}menu.onclick=function(){setMenu(!drawer.classList.contains('open'))};close.onclick=function(){setMenu(false)};search.onclick=function(){setSearch(true)};searchClose.onclick=function(){setSearch(false)};shade.onclick=function(){setMenu(false);setSearch(false)};document.addEventListener('keydown',function(e){if(e.key==='Escape'){setMenu(false);setSearch(false)}});var mobile=document.querySelector('[data-mobile-link]');if(mobile)mobile.href=document.body.dataset.mobile||'index.html?view=mobile';var target=new Date('2026-10-23T10:00:00+05:30').getTime(),out=document.querySelector('[data-shared-clock]');function pad(n){return String(n).padStart(2,'0')}function tick(){var d=Math.max(0,target-Date.now()),dd=Math.floor(d/864e5),hh=Math.floor(d/36e5)%24,mm=Math.floor(d/6e4)%60;out.textContent=dd+'d '+pad(hh)+'h '+pad(mm)+'m'}tick();setInterval(tick,60000)})();</script>'''

for filename,mobile in pages.items():
    p=Path(filename); h=p.read_text()
    if 'id="shared-desktop-system"' in h: continue
    h=h.replace('</head>',CSS+'</head>',1)
    body_start=h.find('<body')
    body_end=h.find('>',body_start)
    h=h[:body_end]+f' data-mobile="{mobile}"'+h[body_end:]
    body_end=h.find('>',body_start)
    h=h[:body_end+1]+NAV+h[body_end+1:]
    h=h.replace('</body>',JS+'</body>',1)
    p.write_text(h)

p=Path('context.md');text=p.read_text()
text=text.replace('Other desktop pages retain their current inline mastheads until navigation is intentionally synchronized.','All 14 desktop pages now use the same homepage-derived 88px navigation, 170px logo, Search and three document utilities, countdown, Login, Register, and single-column menu drawer.',1)
needle='Desktop homepage section introductions share one editorial grid token:'
text=text.replace(needle,'All desktop pages use the shared 1680px shell, 32px minimum gutters, 13.2px eyebrow labels, and homepage navigation. Desktop homepage section introductions share one editorial grid token:',1)
p.write_text(text)
